blocs/user-account-avatar/style.css.content:
:host {
    display: block;
    color: inherit;
    font: inherit;
}

* {
    box-sizing: border-box;
}

.field {
    display: grid;
    justify-items: start;
    gap: .5rem;
}

.picker {
    position: relative;
    display: block;
    width: 7rem;
    height: 7rem;
    cursor: pointer;
}

.frame {
    display: grid;
    width: 100%;
    height: 100%;
    place-items: center;
    overflow: hidden;
    border: 1px solid var(--account-avatar-border, var(--border-default, color-mix(in srgb, currentColor 20%, transparent)));
    border-radius: 50%;
    background: var(--account-avatar-background, var(--bg-subtle, Canvas));
    color: var(--text-muted, color-mix(in srgb, currentColor 42%, transparent));
}

.frame img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.placeholder {
    display: grid;
    place-items: center;
}

.placeholder svg {
    width: 3.25rem;
    height: 3.25rem;
    fill: none;
    stroke: currentColor;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 1.5;
}

.action {
    position: absolute;
    right: -.125rem;
    bottom: -.125rem;
    display: grid;
    width: 2.25rem;
    height: 2.25rem;
    place-items: center;
    border: 3px solid var(--bg-base, Canvas);
    border-radius: 50%;
    background: var(--account-avatar-accent, var(--primary-base, CanvasText));
    color: var(--account-avatar-action-color, var(--primary-foreground, Canvas));
    box-shadow: 0 .125rem .4rem color-mix(in srgb, CanvasText 18%, transparent);
    transition: transform 120ms ease;
}

.action svg {
    width: 1rem;
    height: 1rem;
    fill: none;
    stroke: currentColor;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 2;
}

.picker:hover .action {
    transform: scale(1.05);
}

.picker:has(input:focus-visible) .frame {
    outline: 2px solid var(--account-avatar-accent, var(--primary-base, currentColor));
    outline-offset: 3px;
}

input,
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    overflow: hidden;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
}

small {
    color: var(--text-muted, color-mix(in srgb, currentColor 65%, transparent));
}

:host([disabled]) {
    opacity: .6;
}

:host([disabled]) .picker {
    cursor: not-allowed;
}

[hidden] {
    display: none !important;
}

