                            { label: "None", value: "none" },
                            { label: "S", value: "sm" },
                            { label: "M", value: "md" },
                            { label: "L", value: "lg" },
                            { label: "Pill", value: "pill" },
                        ],
                    },
                    {
                        type: "segmented",
                        label: "Shadow",
                        attribute: "toast-shadow",
                        defaultValue: "none",
                        options: [
                            { label: "None", value: "none" },
                            { label: "S", value: "sm" },
